  ('3f045dc3-b067-5569-b753-0e4872afd634', null, (select id from public.skills where slug = 'read-g8-character-setting-plot'), null, 'hard',
   $q$The heron says, "I mistook my stillness for wisdom." What change in her character does this line show?$q$, $q$[{"text":"She decides that patience is useless and that she should always hurry.","is_correct":false,"misconception_token":"overgeneralization"},{"text":"She realizes she should have moved downstream much earlier in summer.","is_correct":false,"misconception_token":"confuses-cause-effect"},{"text":"She still blames the beaver for making the water near her spot deeper.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"She sees that the patience she was proud of kept her from planning ahead.","is_correct":true}]$q$::jsonb, $q$She sees that the patience she was proud of kept her from planning ahead.$q$, $q$She once boasted of her patience, but now admits it was not wisdom because she did not prepare for the dry months. The moral says patience without foresight fails, not that patience itself is useless.$q$, 'draft', '1b0c7c86-144b-5240-8826-96be22cda1aa')
