-- Passage rg8-character-setting-plot-p06
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('7668d4a1-3bec-54ae-92e0-e86ca1d00d40', 'rg8-character-setting-plot-p06', (select id from public.skills where slug = 'read-g8-character-setting-plot'), null,
        '6-8', $q$Low Tide$q$, $q$My uncle woke me early, in the gray.
"The tide is lowest now," he said. "Bring the notebook."
I grumbled, but I went. The sand was cold.

He knelt beside a pool between the rocks
and pointed at a crab no bigger than a coin.
"Count them," he said. "Write down every one."
I counted seven crabs and two pale stars.

"Why count?" I asked. "They'll all be here next year."
He did not answer right away. He turned
a page back in his notebook, then another,
and showed me numbers written years ago.
Fourteen. Eleven. Ten. Then nine. Then seven.

"Your grandmother began this list," he said.
"I kept it going after she moved inland.
Someone should notice when a small thing changes."

I took the pencil from him. In the wind,
I wrote the date, the pool, the seven crabs,
and underneath, in letters very small,
I added one more line: I will come back.$q$, 'draft')
