-- Passage rg8-character-setting-plot-p07
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('bbba1120-d0e4-5933-95a0-3bc377ecc9bd', 'rg8-character-setting-plot-p07', (select id from public.skills where slug = 'read-g8-character-setting-plot'), null,
        '6-8', $q$Bus 9$q$, $q$Every morning, Marcus walked his little brother Eli to the corner of Fifth and Grant to catch Bus 9. Marcus was in eighth grade, and Eli was in third. Their mother left for work at six, so the job belonged to Marcus.

On Wednesday, the bus was eight minutes late. Eli was hopping from one foot to the other, talking about a class trip to the planetarium. Marcus was barely listening. He was thinking about his science quiz and the chapter he had not finished reading.

When the bus finally pulled up, Eli patted his jacket pockets. Then he patted them again. His face went pale.

"My permission slip," he said. "It's on the kitchen table. Ms. Ruiz said nobody goes without a slip."

The bus doors folded open. The driver looked at them and waited.

Marcus thought fast. If he ran home for the slip, he would miss his own bus and walk into first period late, right in the middle of the quiz. If he did nothing, Eli would spend the trip day sitting in the school library.

"Go on," Marcus told him. "I'll bring it."

"You'll be late," Eli said.

"I know. Get on the bus."

Eli climbed the steps and pressed his face to the window as the bus pulled away. Marcus ran the four blocks home, grabbed the slip, and carried it to Eli's school office. He reached his own classroom twenty minutes after the bell.

His teacher pointed to an empty desk and slid a quiz onto it. "You can start now and finish at lunch," she said.

Marcus sat down. For once, he did not mind giving up his lunch period.$q$, 'draft')
